import{r as a,o,a as r,b as t,d as i,w as l,F as c,c as n,e}from"./app.756eaed4.js";import{_ as d}from"./plugin-vue_export-helper.21dcd24c.js";const p={},u=n(`<h1 id="configuring-the-extension" tabindex="-1"><a class="header-anchor" href="#configuring-the-extension" aria-hidden="true">#</a> Configuring the extension</h1><p>Configuration for IMS Explorer for VS Code extension settings is managed through <strong>VS Code Settings</strong>.</p><h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h2><p>To open the extension settings for IMS Explorer for VS Code, click the Manage button located at the bottom of the Activity Bar. This button is indicated by a cog or gear. Select <strong>Settings</strong> and locate the <strong>IMS Explorer</strong> settings within the Extensions list or by using the search bar to filter results. Alternatively, you can directly update the <code>setting.json</code> file directly to add define the properties which are shown .</p><h2 id="java-home" tabindex="-1"><a class="header-anchor" href="#java-home" aria-hidden="true">#</a> Java Home</h2><p>Used to specify an absolute path to a supported Java installation to be used by IMS Explorer for VS Code.</p><p><strong>macOS example:</strong></p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.connection.property.javaHome&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/Library/Java/JavaVirtualMachines/jdk21/Contents/Home&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Windows example:</strong></p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.connection.property.javaHome&quot;</span><span class="token operator">:</span> <span class="token string">&quot;C:\\Program Files\\Java\\jdk21&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="jvm-arguments" tabindex="-1"><a class="header-anchor" href="#jvm-arguments" aria-hidden="true">#</a> JVM Arguments</h2><p>Configure JVM arguments for IMS connections, including memory allocation and other Java system properties:</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.connection.property.jvmArgs&quot;</span><span class="token operator">:</span> <span class="token string">&quot;-Xms2g -Xmx4g -Denv=prod&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Common use cases include setting heap size (<code>-Xms</code> and <code>-Xmx</code>), enabling debug options, or configuring SSL properties.</p><h2 id="logging-level" tabindex="-1"><a class="header-anchor" href="#logging-level" aria-hidden="true">#</a> Logging Level</h2><p>Controls the level in the IMS Explorer logs. Default logging level is <strong>INFO</strong>. Changes take effect immediately.</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.logging.level&quot;</span><span class="token operator">:</span> <span class="token string">&quot;INFO&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Logs appear in the <strong>Output</strong> panel under:</p><ul><li>IBM IMS Explorer for VS Code</li><li>IBM IMS Explorer LSP Server <ul><li>Any JDBC or SQL related errors should be expected from this log panel</li></ul></li></ul><h2 id="ims-connection-configuration" tabindex="-1"><a class="header-anchor" href="#ims-connection-configuration" aria-hidden="true">#</a> IMS Connection Configuration</h2>`,20),g=e("For connection-level configuration options\u2014including SSL certificates, catalog visibility, performance tuning, and tracing\u2014see "),h=e("Configuring IMS connections"),m=e("."),f=n(`<h2 id="workspace-location" tabindex="-1"><a class="header-anchor" href="#workspace-location" aria-hidden="true">#</a> Workspace Location</h2><p>Defines where extension-related files\u2014such as <code>ims.connections.json</code> are stored. This allows consistent management of IMS project configuration files and enables sharing through version control. You can modify the workspace location using <strong>VS Code Settings</strong>.</p><p>To access VS Code extension settings, click the cog wheel icon in the bottom of the activity bar</p><h3 id="macos-default" tabindex="-1"><a class="header-anchor" href="#macos-default" aria-hidden="true">#</a> macOS Default</h3><ul><li>The default directory is the user\u2019s home directory.<div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.property.ImsWorkspace&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/Users/&lt;username&gt;/.vscode/ims-workspace&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><h3 id="windows-default" tabindex="-1"><a class="header-anchor" href="#windows-default" aria-hidden="true">#</a> Windows Default</h3><ul><li>The default directory is the current user profile directory.<div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.property.ImsWorkspace&quot;</span><span class="token operator">:</span> <span class="token string">&quot;C:\\Users\\%USERNAME%\\.vscode\\ims-workspace&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><h2 id="expansion-warning-limit" tabindex="-1"><a class="header-anchor" href="#expansion-warning-limit" aria-hidden="true">#</a> Expansion warning limit</h2><p>Specifies the number of items after which a warning is shown before loading a large list in the tree view.</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token property">&quot;ims.explorer.treeView.ExpansionWarningLimit&quot;</span><span class="token operator">:</span> <span class="token number">500</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,10);function v(b,x){const s=a("RouterLink");return o(),r(c,null,[u,t("p",null,[g,i(s,{to:"/Docs/Configuring-IMS-connections.html"},{default:l(()=>[h]),_:1}),m]),f],64)}var j=d(p,[["render",v]]);export{j as default};
